 1	import java.util.Arrays;
 2	
 3	public final class BubbleSort {
 4	    private static final int[] SAMPLE_ARRAY = {64, 34, 25, 12, 22, 11, 90};
 5	    private static final String SORTED_ARRAY_LABEL = "Sorted array:";
 6	
 7	    private BubbleSort() {
 8	    }
 9	
10	    public static void sort(int[] array) {
11	        sortInPlace(array);
12	    }
13	
14	    public static int[] sortedCopy(int[] array) {
15	        if (array == null) {
16	            return null;
17	        }
18	
19	        int[] copy = Arrays.copyOf(array, array.length);
20	        sortInPlace(copy);
21	        return copy;
22	    }
23	
24	    public static String toDisplayString(int[] array) {
25	        if (array == null) {
26	            return "null";
27	        }
28	
29	        StringBuilder builder = new StringBuilder();
30	        for (int index = 0; index < array.length; index++) {
31	            if (index > 0) {
32	                builder.append(' ');
33	            }
34	            builder.append(array[index]);
35	        }
36	        return builder.toString();
37	    }
38	
39	    private static void swap(int[] array, int leftIndex, int rightIndex) {
40	        int temp = array[leftIndex];
41	        array[leftIndex] = array[rightIndex];
42	        array[rightIndex] = temp;
43	    }
44	
45	    private static void sortInPlace(int[] array) {
46	        if (array == null || array.length < 2) {
47	            return;
48	        }
49	
50	        for (int unsortedEnd = array.length - 1; unsortedEnd > 0; unsortedEnd--) {
51	            boolean swapped = false;
52	
53	            for (int index = 0; index < unsortedEnd; index++) {
54	                if (array[index] > array[index + 1]) {
55	                    swap(array, index, index + 1);
56	                    swapped = true;
57	                }
58	            }
59	
60	            if (!swapped) {
61	                return;
62	            }
63	        }
64	    }
65	
66	    public static void main(String[] args) {
67	        System.out.println(formatSortedSample());
68	    }
69	
70	    private static int[] buildSampleArray() {
71	        return Arrays.copyOf(SAMPLE_ARRAY, SAMPLE_ARRAY.length);
72	    }
73	
74	    private static String formatSortedSample() {
75	        int[] sortedSample = sortedCopy(buildSampleArray());
76	        return SORTED_ARRAY_LABEL + System.lineSeparator() + toDisplayString(sortedSample);
77	    }
78	}
